SELECT *
  FROM agent_task_operation_log
 WHERE task_id = #{taskId}
   AND create_time >= #{beginTime}
   AND create_time <= #{endTime}
 ORDER BY create_time ASC, id ASC

SELECT *
  FROM agent_task_operation_log
 WHERE task_id = #{taskId}
   AND request_idempotency_key = #{requestIdempotencyKey}
 ORDER BY id DESC
 LIMIT 1
